                <button className={`theme-card ${appearanceSettings.themeMode === "system" ? "selected" : ""}`} onClick={() => updateAppearance({ themeMode: "system" })}>
                  <span className={`theme-preview ${theme === "dark" ? "dark-preview" : "light-preview"}`} />
