  background: color-mix(in srgb, var(--accent-soft) 38%, var(--surface));
}

.settings-modal .admin-operations-settings-stack .admin-ops-detail strong {
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 850;
}

.settings-modal .admin-operations-settings-stack .admin-ops-detail p {
  margin: 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
}

@media (max-width: 960px) {
  .settings-modal {
    width: calc(100vw - 24px);
    height: calc(100vh - 24px);
    grid-template-columns: 240px minmax(0, 1fr);
  }

  .settings-modal .appearance-panels-grid,
  .settings-modal .theme-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .settings-modal .advanced-settings-stack .security-card-grid,
  .settings-modal .account-settings-stack .security-card-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .settings-modal .profile-settings-form-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .settings-modal .profile-presence-segment {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .settings-modal .privacy-settings-stack .security-card-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .settings-modal .notification-settings-time-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .settings-modal .voice-settings-stack .security-card-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .settings-modal .diagnostics-metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .settings-modal .diagnostics-logs-filters {
    grid-template-columns: minmax(0, 1fr);
  }

  .settings-modal .diagnostics-log-row {
    grid-template-columns: minmax(0, 1fr);
    gap: 4px;
  }

  .settings-modal .diagnostics-log-row span {
    grid-column: 1 / -1;
  }

  .settings-modal .admin-operations-settings-stack .admin-ops-layout {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .settings-modal .admin-operations-settings-stack .admin-ops-layout nav {
    grid-auto-flow: column;
    grid-auto-columns: max-content;
    overflow-x: auto;
    overflow-y: hidden;
    border-right: 0;
    border-bottom: 1px solid color-mix(in srgb, var(--border) 84%, transparent);
  }

  .settings-modal .admin-operations-settings-stack .admin-ops-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.settings-modal .legal-settings-stack {
  display: grid;
  gap: 16px;
  max-width: none;
  border: 0;
  background: transparent;
  padding: 0;
}

.settings-modal .legal-settings-section {
  display: grid;
  gap: 10px;
}

.settings-modal .legal-settings-section-title {
  margin: 0;
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 850;
  letter-spacing: -0.01em;
}

.settings-modal .legal-settings-panel {
  display: grid;
  gap: 8px;
}

.settings-modal .legal-settings-panel > button {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 14px;
  border: 1px solid color-mix(in srgb, var(--border) 88%, transparent);
  border-radius: 14px;
  background: var(--surface);
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
  box-shadow: var(--shadow-soft);
  transition: border-color 140ms ease, background 140ms ease;
}

.settings-modal .legal-settings-panel > button:hover {
  border-color: color-mix(in srgb, var(--accent) 24%, var(--border));
  background: color-mix(in srgb, var(--accent-soft) 28%, var(--surface));
}

.settings-modal .legal-settings-panel > button:focus-visible {
  outline: 0;
  box-shadow: var(--focus-ring);
}

.settings-modal .legal-settings-panel > button span {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.settings-modal .legal-settings-panel > button strong {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 850;
}

.settings-modal .legal-settings-panel > button small,
.settings-modal .legal-settings-footer {
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
}

.settings-modal .legal-settings-footer {
  display: block;
}

@media (max-width: 720px) {
  .settings-modal {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
  }

  .settings-modal .settings-nav {
    max-height: 180px;
  }

  .settings-modal .settings-tabs {
    grid-auto-flow: column;
    grid-auto-columns: max-content;
    overflow-x: auto;
    overflow-y: hidden;
  }

  .account-summary-meta {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .settings-modal .theme-card {
    transition: none;
  }
}
